-- Product notes for Instituto → Novedades. One row per note. Same list for every institute.
-- RLS is on. There is no anon or authenticated policy. The server reads with the Pulsar service role.
-- A later note is a new insert in a later Pulsar migration. Do not put the list back in TypeScript.

create table if not exists public.platform_changelog_entries (
  id text primary key,
  published_on date not null,
  area text not null check (area in ('academic', 'finance', 'registrations', 'parent', 'portal', 'events', 'cms', 'admin', 'communications', 'site')),
  title_es text not null,
  title_en text not null,
  title_pt text not null,
  summary_es text not null,
  summary_en text not null,
  summary_pt text not null,
  position integer not null,
  created_at timestamptz not null default now()
);

alter table public.platform_changelog_entries enable row level security;

create index if not exists platform_changelog_entries_published_idx
  on public.platform_changelog_entries (published_on desc, position asc);

insert into public.platform_changelog_entries (
  id, published_on, area, title_es, title_en, title_pt, summary_es, summary_en, summary_pt, position
) values
